[TestMethod]
public void ApplyCoupon_NullCoupon_Throws()
{
    var calc = new DiscountCalculator();
    Assert.ThrowsException<ArgumentNullException>(
        () => calc.ApplyCoupon(100m, null!));
}

// Minimum floor: coupon can't reduce below 1.00
[TestMethod]
public void ApplyCoupon_CouponReducesBelowFloor_ReturnsMinimum()
{
    var calc = new DiscountCalculator();
    // FLAT50 on a $10 order → 10 - 50 = -40 → clamped to 1.00
    Assert.AreEqual(1.00m, calc.ApplyCoupon(10m, "FLAT50"));
}

[TestMethod]
public void ApplyCoupon_CouponReducesToExactlyFloor_ReturnsFloor()
{
    var calc = new DiscountCalculator();
    // FLAT5 on $6.00 → 6 - 5 = 1.00 (exactly floor)
    Assert.AreEqual(1.00m, calc.ApplyCoupon(6.00m, "FLAT5"));
}

[TestMethod]
public void ApplyCoupon_CouponReducesAboveFloor_ReturnsResult()
{
    var calc = new DiscountCalculator();
    // FLAT5 on $100 → 100 - 5 = 95
    Assert.AreEqual(95.00m, calc.ApplyCoupon(100m, "FLAT5"));
}

// Unknown coupon code → no discount
[TestMethod]
public void ApplyCoupon_UnknownCoupon_ReturnsOriginalTotal()
{
    var calc = new DiscountCalculator();
    Assert.AreEqual(100m, calc.ApplyCoupon(100m, "BOGUS"));
}

// SAVE20 coupon
[TestMethod]
public void ApplyCoupon_Save20_Applies20Percent()
{
    var calc = new DiscountCalculator();
    Assert.AreEqual(80m, calc.ApplyCoupon(100m, "SAVE20"));
}

// Case insensitivity
[TestMethod]
public void ApplyCoupon_LowercaseCoupon_StillApplies()
{
    var calc = new DiscountCalculator();
    Assert.AreEqual(90m, calc.ApplyCoupon(100m, "save10"));
}

[TestMethod]
public void ApplyCoupon_ZeroTotal_Throws()
{
    var calc = new DiscountCalculator();
    Assert.ThrowsException<ArgumentOutOfRangeException>(
        () => calc.ApplyCoupon(0m, "SAVE10"));
}

